class TmPoint{final double e,n;final int dom;const TmPoint(this.e,this.n,this.dom);}
TmPoint toTm3(double lat,double lon){final p=latLngToTm3(LatLng(lat,lon));return TmPoint(p.easting,p.northing,p.dom);}
class SavedPoint{final int no;final DateTime time;final Position pos;final TmPoint tm;SavedPoint(this.no,this.time,this.pos,this.tm);}
