 void _addCoordinate(){final e=double.tryParse(_eCtrl.text.replaceAll(',','.')),n=double.tryParse(_nCtrl.text.replaceAll(',','.'));if(e==null||n==null)return;final dom=_tm?.dom??33;if(_cad.state.mode==CadDrawMode.none)_cad.setMode(CadDrawMode.polyline);_cad.addExactVertex(tm3ToLatLng(e,n,dom));Navigator.pop(context);}
