 void _stakeout(){if(_tm==null)return;final te=double.tryParse(_eCtrl.text.replaceAll(',','.')),tn=double.tryParse(_nCtrl.text.replaceAll(',','.'));if(te==null||tn==null)return;final de=te-_tm!.e,dn=tn-_tm!.n,d=math.sqrt(de*de+dn*dn);var az=math.atan2(de,dn)*180/math.pi;if(az<0)az+=360;showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Aplikasyon',style:Theme.of(context).textTheme.titleLarge),Text('Mesafe: ${d.toStringAsFixed(3)} m',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text('Azimut: ${az.toStringAsFixed(4)}°'),Text('Dogu: ${de.toStringAsFixed(3)} m  Kuzey: ${dn.toStringAsFixed(3)} m')])));}
